WITH "per" AS (SELECT "t1"."region" AS "region", "t1"."branch_id" AS "branch_id", MAX("t1"."branch_name") AS "branch_id_label", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN "t0"."net_amount" END) AS "revenue" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND ("t1"."branch_id" IS NOT NULL) AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t1"."region", "t1"."branch_id") SELECT "per"."region" AS "region", AVG("per"."revenue") AS "avg_revenue_per_branch", MAX("per"."revenue") AS "best_branch_revenue" FROM "per" GROUP BY "per"."region" ORDER BY "avg_revenue_per_branch" DESC LIMIT 1000
